from zoneinfo import ZoneInfo
import hashlib,json,shutil,sys
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'runs/flyvis_local_gate_stress_20261105';sys.path.insert(0,str(ROOT))
from scripts.obsidian_system_problems import load,problem_path
from scripts.obsidian_fundamental_overview import build
from scripts.audit_fundamental_obsidian import audit
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 r=json.loads((OUT/'report.json').read_text(encoding='utf-8'));a=json.loads((OUT/'independent_audit.json').read_text(encoding='utf-8'));assert a['passed'] and a['report_sha256']==sha(OUT/'report.json');s=r['summaries'];assert not r['preliminary_gate'] and len(s)==7
 refs=['runs/flyvis_local_gate_stress_20261105/'+x for x in ('protocol.json','report.json','independent_audit.json')]
 msg=(f"На восьми новых для недавних пилотов сценах, по 32 зависимых искусственных условия каждого вида: при плавном изменении освещения на неподвижной сцене локальное правило ошибочно сообщило о движении в {s['light_ramp']['local_moving']}/{s['light_ramp']['n']}, глобальное — в {s['light_ramp']['global_decision_moving']}/{s['light_ramp']['n']}. При локальном объекте обычного контраста ошибочно принят покой локальным правилом в {s['local_normal']['local_stationary']}/{s['local_normal']['n']}, глобальным в {s['local_normal']['global_decision_stationary']}/{s['local_normal']['n']}; при ослабленном контрасте — соответственно {s['local_low']['local_stationary']}/{s['local_low']['n']} и {s['local_low']['global_decision_stationary']}/{s['local_low']['n']}. При обычном покое локальное правило сообщило о движении в {s['still']['local_moving']}/{s['still']['n']}; при искусственном движении камеры и движении камеры с объектом не приняло движение за покой ни в одном из 32 условий каждой группы. Заранее заданный составной критерий не выполнен. Восемь фоновых изображений взяты из обучающей части BDD; сцены могли использоваться в других работах проекта. Модель FlyVis и реальные движущиеся видео не проверены.")
